        // ── Embedded Extension Files in Base64 (Guarantees Extension works on ANY machine 100%) ──
        private static readonly Dictionary<string, string> EmbeddedExtensionFiles = new()
        {
            ["manifest.json"] = "",
            ["background.js"] = "",
            ["content.js"] = "",
            ["config.json"] = "eyJ3aWQiOiAxLCAicG9ydCI6IDUwMDAsICJldmVudF9pZCI6ICJhMjk3Y2JkNy1jMWM0LTQ0OGYtOWU5Zi0wZjJhMzVkMjhhYzMifQ==",
