        public static string GetBotProfilesBaseDir()
        {
            string path = Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.LocalApplicationData), @"Google\Chrome\BotProfiles");
            Directory.CreateDirectory(path);
            return path;
        }

        public static string GetChromeExePath()
        {
            string baseDir = AppDomain.CurrentDomain.BaseDirectory;
            string[] portablePaths = {
                Path.Combine(baseDir, @"chrome-win64\chrome.exe"),
                Path.Combine(baseDir, @"chrome\chrome.exe"),
                Path.Combine(baseDir, @"..\..\..\chrome-win64\chrome.exe"),
                Path.Combine(baseDir, @"..\..\..\..\FastLoginSuite_Login_Source\chrome-win64\chrome.exe"),
            };

            foreach (var p in portablePaths)
            {
                if (File.Exists(p)) return Path.GetFullPath(p);
            }

            string localApp = Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.LocalApplicationData), @"Google\Chrome\Application\chrome.exe");
            if (File.Exists(localApp)) return localApp;

            string progFiles = @"C:\Program Files\Google\Chrome\Application\chrome.exe";
            if (File.Exists(progFiles)) return progFiles;

            string progFilesX86 = @"C:\Program Files (x86)\Google\Chrome\Application\chrome.exe";
            if (File.Exists(progFilesX86)) return progFilesX86;

            // Registry check (HKCU / HKLM)
            try
            {
                using var key = Microsoft.Win32.Registry.CurrentUser.OpenSubKey(@"Software\Microsoft\Windows\CurrentVersion\App Paths\chrome.exe");
                if (key != null)
                {
                    var val = key.GetValue("") as string;
                    if (!string.IsNullOrEmpty(val) && File.Exists(val)) return val;
                }
            }
            catch { }

            try
            {
                using var key = Microsoft.Win32.Registry.LocalMachine.OpenSubKey(@"Software\Microsoft\Windows\CurrentVersion\App Paths\chrome.exe");
                if (key != null)
                {
                    var val = key.GetValue("") as string;
                    if (!string.IsNullOrEmpty(val) && File.Exists(val)) return val;
                }
            }
            catch { }

            return "chrome.exe";
        }

        public static string GetExtensionPath()
        {
            string baseDir = AppDomain.CurrentDomain.BaseDirectory;
            string extDir = Path.Combine(baseDir, "extension");
            if (Directory.Exists(extDir)) return Path.GetFullPath(extDir);

            string devExt = Path.Combine(baseDir, "..", "..", "..", "extension");
            if (Directory.Exists(devExt)) return Path.GetFullPath(devExt);

            string devExt2 = Path.Combine(baseDir, "..", "..", "..", "..", "FastLoginSuite_Login_Source", "extension");
            if (Directory.Exists(devExt2)) return Path.GetFullPath(devExt2);

            return extDir;
        }

        public static void EnsureExtensionFiles(string targetDir)
        {
            Directory.CreateDirectory(targetDir);
            string extDir = GetExtensionPath();

            // 1. Try copy from external extension folder if available
            if (Directory.Exists(extDir) && Path.GetFullPath(extDir) != Path.GetFullPath(targetDir))
            {
                try
                {
                    foreach (var file in Directory.GetFiles(extDir))
                    {
                        string dest = Path.Combine(targetDir, Path.GetFileName(file));
                        File.Copy(file, dest, true);
                    }
                }
                catch { }
            }

            // 2. Extract embedded files for any missing or 0-byte file (100% foolproof fallback)
            foreach (var kvp in EmbeddedExtensionFiles)
            {
                string filePath = Path.Combine(targetDir, kvp.Key);
                if (!File.Exists(filePath) || new FileInfo(filePath).Length == 0)
                {
                    try
                    {
                        byte[] data = Convert.FromBase64String(kvp.Value);
                        File.WriteAllBytes(filePath, data);
                    }
                    catch { }
                }
            }

            // 3. Also make sure the local extension directory next to the exe is populated
            string baseExt = Path.Combine(AppDomain.CurrentDomain.BaseDirectory, "extension");
            if (!Directory.Exists(baseExt))
            {
                try
                {
                    Directory.CreateDirectory(baseExt);
                    foreach (var kvp in EmbeddedExtensionFiles)
                    {
                        string dest = Path.Combine(baseExt, kvp.Key);
                        if (!File.Exists(dest))
                        {
                            byte[] data = Convert.FromBase64String(kvp.Value);
                            File.WriteAllBytes(dest, data);
                        }
                    }
                }
                catch { }
            }
        }

        public static List<ChromeProfileInfo> GetBotProfiles(int expectedCount = 0)
        {
            var list = new List<ChromeProfileInfo>();
            string baseDir = GetBotProfilesBaseDir();
            if (!Directory.Exists(baseDir)) return list;

            var dirs = Directory.GetDirectories(baseDir, "worker_*");
            var sortedDirs = new List<(int wid, string dir)>();

            foreach (var dir in dirs)
            {
                string name = Path.GetFileName(dir);
                if (name.StartsWith("worker_") && int.TryParse(name.Substring("worker_".Length), out int wid))
                {
                    sortedDirs.Add((wid, dir));
                }
            }

            sortedDirs.Sort((a, b) => a.wid.CompareTo(b.wid));

            foreach (var item in sortedDirs)
            {
                list.Add(new ChromeProfileInfo
                {
                    WorkerId = item.wid,
                    DirectoryName = $"worker_{item.wid}",
                    DisplayName = $"HOF Bot {item.wid}",
                    Path = item.dir,
                    ExistsOnDisk = true
                });
            }

            return list;
        }

        public static bool CreateBotProfiles(int count)
        {
            try
            {
                string baseDir = GetBotProfilesBaseDir();
                string extDir = GetExtensionPath();

                for (int i = 1; i <= count; i++)
                {
                    InitializeWorkerSession(i, baseDir, extDir);
                }
                return true;
            }
            catch (Exception ex)
            {
                Debug.WriteLine($"Error creating bot profiles: {ex.Message}");
                return false;
            }
        }

        public static string InitializeWorkerSession(int wid, string baseDir, string extDir)
        {
            string profilePath = Path.Combine(baseDir, $"worker_{wid}");
            string defaultDir = Path.Combine(profilePath, "Default");
            string workerExt = Path.Combine(profilePath, "extension");

            Directory.CreateDirectory(profilePath);
            Directory.CreateDirectory(defaultDir);
            Directory.CreateDirectory(workerExt);

            // 1. Skip First Run
            string firstRunFile = Path.Combine(profilePath, "First Run");
            if (!File.Exists(firstRunFile))
            {
                try { File.WriteAllText(firstRunFile, ""); } catch { }
            }

            // 2. Ensure all extension files exist with 100% reliability
            EnsureExtensionFiles(workerExt);

            // 2.5 If wid > 1 and worker_1 has configured session (Secure Preferences), clone it
            if (wid > 1)
            {
                string w1Default = Path.Combine(baseDir, "worker_1", "Default");
                string w1SecPref = Path.Combine(w1Default, "Secure Preferences");
                string curSecPref = Path.Combine(defaultDir, "Secure Preferences");
                if (File.Exists(w1SecPref) && !File.Exists(curSecPref))
                {
                    try
                    {
                        CopyDirectory(w1Default, defaultDir, true);
                    }
                    catch { }
                }
            }

            // 3. Pre-configure Preferences (Always ensure Developer Mode is ON)
            string prefFile = Path.Combine(defaultDir, "Preferences");
            try
            {
                JsonObject prefs = null;
                if (File.Exists(prefFile))
                {
                    try
                    {
                        string json = File.ReadAllText(prefFile);
                        prefs = JsonNode.Parse(json) as JsonObject;
                    }
                    catch { }
                }

                if (prefs == null)
                {
                    prefs = new JsonObject();
                }

                if (!prefs.ContainsKey("extensions") || !(prefs["extensions"] is JsonObject))
                {
                    prefs["extensions"] = new JsonObject();
                }
                var extObj = prefs["extensions"].AsObject();
                if (!extObj.ContainsKey("ui") || !(extObj["ui"] is JsonObject))
                {
                    extObj["ui"] = new JsonObject();
                }
                extObj["ui"].AsObject()["developer_mode"] = true;

                // Disable "Restore pages? Chromium didn't shut down correctly"
                var profObj = new JsonObject
                {
                    ["exit_type"] = "Normal",
                    ["exited_cleanly"] = true
                };
                prefs["profile"] = profObj;

                File.WriteAllText(prefFile, prefs.ToJsonString(new JsonSerializerOptions { WriteIndented = true }));
            }
            catch { }

            // 4. Generate Batch Launcher Shortcut (.bat) inside profile for 1-click launch with extension
            try
            {
                string chromeExe = GetChromeExePath();
                string batFile = Path.Combine(profilePath, $"Launch_Worker_{wid}.bat");
                string batContent = $"@echo off\r\nstart \"\" \"{chromeExe}\" \"--user-data-dir={profilePath}\" \"--load-extension={workerExt}\" --no-profile-picker --disable-session-crashed-bubble --hide-crash-restore-bubble --disable-infobars --window-position=0,0 --window-size=460,400 --disable-background-timer-throttling --disable-backgrounding-occluded-windows --disable-renderer-backgrounding --disable-features=CalculateNativeWinOcclusion,PrivateNetworkAccessPermissionPrompt,BlockInsecurePrivateNetworkRequests --no-first-run --no-default-browser-check \"https://passport.thehof.gg/hall-of-fame-web/login#wid={wid}\"\r\n";
                File.WriteAllText(batFile, batContent);
            }
            catch { }

            return workerExt;
        }

        private static void CopyDirectory(string sourceDir, string destinationDir, bool recursive)
        {
            var dir = new DirectoryInfo(sourceDir);
            if (!dir.Exists) return;

            DirectoryInfo[] dirs = dir.GetDirectories();
            Directory.CreateDirectory(destinationDir);

            foreach (FileInfo file in dir.GetFiles())
            {
                string targetFilePath = Path.Combine(destinationDir, file.Name);
                file.CopyTo(targetFilePath, true);
            }

            if (recursive)
            {
                foreach (DirectoryInfo subDir in dirs)
                {
                    string newDestinationDir = Path.Combine(destinationDir, subDir.Name);
                    CopyDirectory(subDir.FullName, newDestinationDir, true);
                }
            }
        }

        public static bool DeleteBotProfiles()
        {
            try
            {
                string baseDir = GetBotProfilesBaseDir();
                if (Directory.Exists(baseDir))
                {
                    Directory.Delete(baseDir, true);
                    Directory.CreateDirectory(baseDir);
                }
                return true;
            }
            catch (Exception ex)
            {
                Debug.WriteLine($"Error deleting bot profiles: {ex.Message}");
                return false;
            }
        }

        public static bool DeleteSingleBotProfile(int wid)
        {
            try
            {
                string baseDir = GetBotProfilesBaseDir();
                string profDir = Path.Combine(baseDir, $"worker_{wid}");
                if (Directory.Exists(profDir))
                {
                    Directory.Delete(profDir, true);
                }
                return true;
            }
            catch (Exception ex)
            {
                Debug.WriteLine($"Error deleting worker_{wid}: {ex.Message}");
                return false;
            }
        }

        public static void LaunchAllProfiles()
        {
            var list = GetBotProfiles();
            foreach (var p in list)
            {
                LaunchProfile(p.WorkerId);
                System.Threading.Thread.Sleep(300);
            }
        }

        public static void LaunchProfile(int wid, string url = "")
        {
            string chromeExe = GetChromeExePath();
            string extDir = GetExtensionPath();
            string baseDir = GetBotProfilesBaseDir();
            string profilePath = Path.Combine(baseDir, $"worker_{wid}");

            // Ensure real session and extension files exist
            string workerExt = InitializeWorkerSession(wid, baseDir, extDir);

            string targetUrl = string.IsNullOrEmpty(url)
                ? $"https://passport.thehof.gg/hall-of-fame-web/login#wid={wid}"
                : url;

            // Fixed window position at top-left of screen
            int x = 0;
            int y = 0;

            // Pure, robust Chrome launch arguments (PNA & Window Occlusion throttling disabled)
            var psi = new ProcessStartInfo
            {
                FileName = chromeExe,
                UseShellExecute = false,
                Arguments = $"\"--user-data-dir={profilePath}\" \"--load-extension={workerExt}\" --no-profile-picker --disable-background-timer-throttling --disable-backgrounding-occluded-windows --disable-renderer-backgrounding --disable-features=CalculateNativeWinOcclusion,PrivateNetworkAccessPermissionPrompt,BlockInsecurePrivateNetworkRequests --window-position={x},{y} --window-size=460,400 --no-first-run --no-default-browser-check \"{targetUrl}\""
            };

            try
            {
                Process.Start(psi);
            }
            catch (Exception ex)
            {
                Debug.WriteLine($"Failed to launch Chrome for worker {wid}: {ex.Message}");
            }
        }
    }
